if(getenv('EMSF_DISPOSABLE_TEST')!=='yes'||!str_contains(ABSPATH,'emsf-integration-direct-')||is_multisite()){throw new RuntimeException('Fixture vereist.');}wp_set_current_user(1);$_SERVER['HTTPS']='on';global $wpdb;$checks=0;$assert=static function($ok,$why)use(&$checks){if(!$ok)throw new RuntimeException($why);$checks++;};
$old=wp_insert_post(['post_type'=>'page','post_status'=>'publish','post_title'=>'Existing destination content','post_content'=>'Existing destination body']);$root=Standalone::storage();$dir=$root.'/incoming-'.wp_generate_uuid4();wp_mkdir_p($dir.'/files');
