$r=Standalone::stage($zip,true);$assert($r['state']==='software_pending','Software staged');$assert((int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$wpdb->posts} WHERE ID=%d",$old))===1,'Staging preserves existing content');
ob_start();Standalone::page();$html=ob_get_clean();$assert(str_contains($html,'data-import-auto="1"'),'Software phase auto-starts');$assert(!str_contains($html,'name="replace_confirmed"'),'No replacement checkbox');
Standalone::installSoftware($r['operation']);$assert(empty(Standalone::state()['backup']),'No software backup receipt');$assert(!(glob($root.'/backup-*')?:[]),'No software backup files');
$fail=static function($data){if(($data['post_name']??'')==='second'){throw new RuntimeException('Injected rollback test');}return $data;};add_filter('wp_insert_post_data',$fail);
try{Standalone::apply($r['operation']);throw new RuntimeException('Expected injected failure');}catch(RuntimeException $e){$assert($e->getMessage()==='Injected rollback test','Import reached data without confirmation');}remove_filter('wp_insert_post_data',$fail);
$assert((int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$wpdb->posts} WHERE ID=%d",$old))===1,'Database rolled back without backup');$assert(empty(Standalone::state()['committed']),'Failed import not committed');$assert(!(glob($root.'/backup-*')?:[]),'No content backup files');
$report=Standalone::importWebsite($r['operation']);$assert($report['ok']&&$report['state']==='released','Automatic import and activation');$assert(get_option('blogname')==='Imported automatically','Options transferred');$assert((int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$wpdb->posts} WHERE ID=%d",$old))===0,'Existing content replaced');$assert(empty(Standalone::state()['backup']),'No backup after completion');$assert(Standalone::state()['backup_mode']==='external','Uses externally managed backup');$assert(!(glob($root.'/backup-*')?:[]),'No backup directory created');$before=(int)$wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->posts}");Standalone::importWebsite($r['operation']);$assert($before===(int)$wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->posts}"),'Retry creates no duplicates');
ob_start();Standalone::page();$finishedHtml=ob_get_clean();$assert(!str_contains($finishedHtml,'Injected rollback test'),'No stale error after successful retry');
